import pandas as pd

def count_apples_and_oranges(boxes: pd.DataFrame, chests: pd.DataFrame) -> pd.DataFrame:
    merged = boxes.merge(chests, on='chest_id', how='left', suffixes=('_box', '_chest'))
    apple_sum = (merged['apple_count_box'] + merged['apple_count_chest'].fillna(0)).sum()
    orange_sum = (merged['orange_count_box'] + merged['orange_count_chest'].fillna(0)).sum()
    return pd.DataFrame({'apple_count': [int(apple_sum)], 'orange_count': [int(orange_sum)]})
